import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"兑下坤上 临：","description":"京氏易传 - 兑下坤上 临：","frontmatter":{"title":"兑下坤上 临：","description":"京氏易传 - 兑下坤上 临："},"headers":[],"relativePath":"zh/classics/jingshi/036.md","filePath":"zh/classics/jingshi/036.md"}'),i={name:"zh/classics/jingshi/036.md"};function r(c,a,o,p,d,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"兑下坤上-临",tabindex:"-1"},[l("兑下坤上 临： "),e("a",{class:"header-anchor",href:"#兑下坤上-临","aria-label":"Permalink to “兑下坤上 临：”"},"​")],-1),e("p",null,"阳长阴消悦而顺，金土应候刚柔分。震入兑，二阳刚，本体阴柔降入临。临者，大也。阳爻健顺，阳交退散。《易》曰：“君子之道”。《易》云：“至于八月有凶”。（虎易注：此处脱漏有字。）【建丑至未也。】阳长，六爻反复，吉凶之道可见矣。【至于八月入遁。】与兑为飞伏，【丁卯木，乙巳火。】九二大夫立世，六五至尊应上位。",-1),e("p",null,"建始丙申至辛丑，【立秋，大寒。】七月积气至六月，吉凶随爻考汙隆。【旺则隆，衰则汙。】积算起辛丑至庚子。【积算起金土入卦，推休咎于六爻。】",-1),e("p",null,"五星从位起荧惑，【荧惑火星，入卦用事。】翼宿从位在丁卯，【二十八宿，翼宿入卦九二爻木上。】分气候三十六。【定阴阳之数，起于三十六积算。】",-1),e("p",null,"坤下见兑，悦、泽，临。阳升阴降，入三阳，乾象入坤，即泰卦。【临卦内象先阳长，逼阴成乾为泰象。】外坤积阴，内兑亦为阴，二阳合体，柔顺之道，不可贞。吉凶以时，配于六位，用于阳长之爻，成临之义。",-1),e("p",null,"六三将变阳爻，至次降入泰卦。【次入地天泰卦。】",-1)])])}const _=s(i,[["render",r]]);export{u as __pageData,_ as default};
